catalog_script_client.script:
var isUpdating = false;

function onChange(control, oldValue, newValue, isLoading) {
    if (isLoading || newValue == '') {
        return;
    }

    if (isUpdating) {
        return;
    }

    if (newValue !== oldValue) {
        isUpdating = true;
        g_form.getReference('select_the_item_you_want_to_return', function(reqByName) {
            g_form.setValue('select_the_item_you_want_to_return', newValue, reqByName.display_name);
            isUpdating = false;
        });
    } else {
        isUpdating = true;
        g_form.setValue('select_the_item_you_want_to_return', newValue);
        isUpdating = false;
    }
}

